style.css:
@-moz-document domain("www.nicovideo.jp"), domain("live.nicovideo.jp") {
/* ============================================================
     niconico Dark
     The 2024 relaunch is built on a design-token system (Panda CSS):
     surfaces, text, borders and inputs all resolve from --colors-*
     custom properties. Re-pointing those tokens flips the modern
     pages (video, ranking, search, comment list) to dark in one pass.
     The home page and profiles still use the legacy DOM, so those
     classes are handled directly below.
     ============================================================ */

  :root {
    color-scheme: dark !important;

    /* ---- Base page + elevated surfaces ---- */
    --colors-layer-background: #14181d !important;
    --colors-layer-surface-high-em: #1c2128 !important;
    --colors-layer-surface-high-em-white: #1c2128 !important;
    --colors-layer-surface-high-em-black: #1c2128 !important;
    --colors-layer-surface-medium-em: #1a1f26 !important;
    --colors-layer-surface-medium-em-white: #1a1f26 !important;
    --colors-layer-surface-medium-em-black: #1a1f26 !important;
    --colors-layer-surface-low-em: #262c33 !important;
    --colors-layer-surface-low-em-black: #262c33 !important;
    --colors-layer-surface-lower-em: #2d333b !important;
    --colors-layer-surface-overlay: #000000cc !important;
    --colors-layer-surface-overlay-black: #000000cc !important;
    --colors-layer-content-overlay: #14181dcc !important;

    /* ---- Text on surfaces ---- */
    --colors-text-on-layer-high-em: #e6edf3 !important;
    --colors-text-on-layer-high-em-white: #e6edf3 !important;
    --colors-text-on-layer-high-em-black: #e6edf3 !important;
    --colors-text-on-layer-medium-em: #c4cdd6 !important;
    --colors-text-on-layer-medium-em-inv: #14181dcc !important;
    --colors-text-on-layer-low-em: #8b949e !important;
    /* "lower emphasis" hint text (e.g. the watch page's "マイリストのはじめから
       連続再生する") only reached 3.9:1 on the page base at #6e7681, failing WCAG
       AA for small text. Lift it just enough to clear 4.5:1 on both the base and
       the elevated card surface while staying dimmer than low-em. */
    --colors-text-on-layer-lower-em: #828b95 !important;
    --colors-text-on-layer-visited: #a9b4c0 !important;

    /* ---- Disabled controls ----
       The site paints every disabled label and icon #666 — a muted-but-legible
       5.7:1 on its own white panels, but only 2.5:1 on our elevated surface, so
       the search-filter's "設定をリセット", disabled tabs and the player's greyed
       controller icons all faded to near-invisible. Lift the whole disabled family
       to a grey that still reads as DISABLED (clearly dimmer than the #c4cdd6 body
       text) while staying legible on dark. `--colors-service-color-ch` is also #666
       but is the CHANNEL brand colour, not a disabled state, so it is left alone. */
    --colors-action-text-on-base_disabled: #7d8590 !important;
    --colors-tab-text-on-base-disabled: #7d8590 !important;
    --colors-icon-base-disabled: #7d8590 !important;
    --colors-icon-watch-controller-disabled: #7d8590 !important;

    /* ---- Borders (soften the bright default lines) ---- */
    --colors-border-base: #262c33 !important;
    --colors-border-high-em: #2d333b !important;
    --colors-action-ui-border: #3a424c !important;

    /* ---- Form inputs (search box, fields) ---- */
    --colors-input-form-background: #0d1117 !important;
    --colors-input-form-input-text: #e6edf3 !important;
    --colors-input-form-placeholder: #8b949e !important;

    /* ---- Icons ---- */
    --colors-icon-base: #c4cdd6 !important;
    --colors-icon-primary: #e6edf3 !important;
    --colors-icon-base-white: #c4cdd6 !important;
    --colors-icon-primary-white: #e6edf3 !important;
    --colors-icon-video-description: #8b949e !important;
    --colors-icon-header-search-base: #8b949e !important;
    --colors-icon-watch-controller-base: #ccd3da !important;

    /* ---- Tabs / on-base actions ---- */
    /* The selected tab pill (comment-list / uploader-videos toggle on the
       watch page, the ranking genre chips) defaults to a near-solid white fill
       (#f2f2f2 @95%); with the light tab label on top it read white-on-white.
       An elevated grey (#2d333b) fixed the legibility but destroyed the
       SEMANTICS: the unselected chips sit on a 10% white track that computes to
       ~#25292e on the page base, so the selected chip stood out at 1.14:1 —
       indistinguishable. Repaint the selected pill with the brand azure surface
       instead: clearly "chosen", and the light label clears 7:1 on it. */
    --colors-tab-base-active: #1f4a78 !important;
    --colors-tab-text-on-base: #c4cdd6 !important;
    --colors-tab-object-on-base: #c4cdd6 !important;
    --colors-tab-text-on-base-active: #e6edf3 !important;
    --colors-tab-object-on-base-active: #e6edf3 !important;
    --colors-tab-text-on-base-hover: #e6edf3 !important;
    --colors-tab-object-on-base-hover: #e6edf3 !important;
    --colors-action-text-on-base: #e6edf3 !important;

    /* ---- Monotone scale (light end maps to dark surfaces;
            the dark end #252525 / #000 already reads as dark and is
            kept for the header bar and the video stage) ---- */
    --colors-monotone--l100: #e6edf3 !important;
    --colors-monotone--l95: #1c2128 !important;
    --colors-monotone--l90: #262c33 !important;
    --colors-monotone--l80: #2d333b !important;
    --colors-monotone--l70: #8b949e !important;

    /* ---- Tooltips / snackbars ---- */
    --colors-tooltip-background: #2d333b !important;
    --colors-tooltip-text-on-background: #e6edf3 !important;
    --colors-snackbar-base: #2d333b !important;
    --colors-snackbar-text-on-base: #e6edf3 !important;

    /* ---- Loading skeleton shimmer ---- */
    --colors-layer-skeleton: linear-gradient(to right, #0000, #ffffff0d, #0000) !important;

    /* ---- niconico accent — keep the brand azure, lift it slightly
            so links/CTAs stay vivid and readable on near-black ---- */
    --colors-action-primary-azure: #2f86e6 !important;
    --colors-action-primary-azure-hover: #4799eb !important;
    --colors-text-on-layer-accent-azure: #5fb0e6 !important;
    --colors-action-text-on-tertiary-azure: #5fb0e6 !important;
    --colors-action-text-on-tertiary-azure-inv: #5fb0e6 !important;
    --colors-icon-primary-azure: #5fb0e6 !important;
    --colors-layer-surface-accent-azure: #1f4a78 !important;

    /* The "lust" accent is the site's semantic red (the ショート "New" flag in
       the left rail, live/error markers). At its own #e61a1a it only reaches
       3.7:1 on the elevated card surface — a fail for the small bold label it
       always carries. Lift it while keeping it unmistakably red. */
    --colors-text-on-layer-accent-lust: #ff5c5c !important;
  }

  /* ============================================================
     Modern (token) pages — a few literal surfaces that bypass
     the token and a couple of util classes Panda emits inline.
     ============================================================ */
  /* Empty / placeholder ad frames sit on white — neutralise the slot
     so it reads as a blank dark panel instead of a bright box. The home
     in-feed slots expose the iframe's own light fill (#f0f0f0) while it is
     unfilled; live's header slot is a light <aside> panel. (A real banner
     creative paints over these, so only the blank state is affected.) */
  .Ads, [class*="Ads"], [class^="Ads"],
  iframe[id*="google_ads"], iframe[id^="ads_"], ins.adsbygoogle,
  aside#header-ad, aside#header-ad > div, aside#header-ad .ad-banner,
  aside.ad-banner, aside.ad-banner > div, aside#player-ad-panel > div {
    background-color: #161b21 !important;
    border-color: #262c33 !important;
  }
  /* Each slot's direct child (the creative's <a>, or the pre-load skeleton) carries
     its own `background:#f0f0f0; border:1px solid #ddd !important` from a
     `.PcUniTop…AdContainer .Ads > *` rule, which the .Ads container rule above never
     reaches — so even a FILLED creative sat in a bright letterbox frame. Match that
     rule's specificity (and land later in the cascade) to beat its !important border. */
  [class*="AdContainer"] .Ads > *, .Ads > a {
    background-color: #161b21 !important;
    border-color: #262c33 !important;
  }
  /* NOTE (verified, do not "fix"): a white 300x250 / 728x90 block sometimes sits
     in these slots. It is NOT the frame's default canvas — with Google's tag
     blocked, the ads.nicovideo.jp frame is transparent and the dark iframe
     background above shows through correctly. The white is a real creative
     rendered inside a NESTED doubleclick.net frame, i.e. genuine ad content that
     happens to be white. `color-scheme: dark` on the outer iframe computes but
     changes nothing, and no CSS from this document can reach a cross-origin
     grandchild frame. Leave it: darkening real content is worse than a white ad. */

  /* Pre-roll video-ad overlay controls (watch page). The skip prompt
     ("○秒後にスキップできます") and the countdown timer color their labels
     through monotone.l95 — which we remap to a dark elevated surface — so over
     the black ad video they read dark-on-dark and nearly vanish. Force the ad
     overlay's own controls back to a light label; the ad creative itself is an
     image/video and is untouched. */
  #nv_watch_VideoAdContainer button,
  #nv_watch_VideoAdContainer [class*="pos_absolute"] { color: #e6edf3 !important; }

  /* Live (live.nicovideo.jp) hover tooltip — its surface hardcodes a light
     fill (#f2f2f2 / #1a1a1a text) that bypasses the tooltip token, so on the
     dark cards it popped up as a white box. Repaint it to the dark tooltip
     surface used everywhere else. */
  .tooltip-layer .tooltip {
    background-color: #2d333b !important;
    color: #e6edf3 !important;
    border-color: #3a424c !important;
  }

  /* Live (live.nicovideo.jp) program-card badges. The "有料" (paid) badge keeps
     a white pill background while our broad legacy label rule lightens its text,
     so light-grey text landed on white and the badge read invisible. Repaint it
     as a dark pill (matching its "会員無料" sibling) and soften the card
     menu-area's light #c4cdd6 divider line to the standard dark border. */
  [class*="pay-program-label"] {
    background-color: #1a1a1a !important;
    border-color: #3a424c !important;
  }
  /* The divider between the card thumbnail and its info row is the menu-area's
     border-TOP (#c4cdd6), not its bottom — the earlier bottom-only rule missed it,
     so a bright light line ran across all 28 program cards. Soften every side. */
  [class*="menu-area"] { border-color: #262c33 !important; }

  /* Live (live.nicovideo.jp) program-card provider-type badges ("公式" / "CH").
     The site colours them by data-provider-type — official = azure, channel =
     gold — but our broad legacy `-label` text pass flattened both to the same
     grey, erasing the official-vs-channel distinction. Restore the two type
     colours (both clear AA on the badge's dark #1a1a1a pill). The tag prefix
     lifts specificity to 0,1,1 so this beats the broad `[class*="-label"]`
     flatten (0,1,0) that lands LATER in the file. */
  span[data-provider-type="official"] { color: #559cff !important; }
  span[data-provider-type="channel"] { color: #d9a300 !important; }

  /* The nicoad-support point count ("22.6万") is painted gold to mark it as an
     ad-support metric; the meta-grey pass flattened it to look like a plain view
     count. Restore the gold, lifted to #d9a300 for AA on the dark card. Tag
     prefixes beat the later `[class*="-count"]` grey rule on specificity. */
  li[class*="nicoad-count"], li[class*="nicoad-count"] span { color: #d9a300 !important; }

  /* The nicoad supporter strip ("提供：〇〇さん") is a 44%-white frosted caption bar
     over the card with near-black text — on the dark card the white went muddy and
     the #1a1a1a text read dark-on-dark. Repaint the strip to a dark frosted bar and
     lift its text to a legible light. */
  [class*="nicoad-frame"] [class*="message"] {
    background-color: rgba(20, 24, 29, 0.6) !important;
  }
  [class*="nicoad-frame"] [class*="message"],
  .advatisor, .advatisor [class*="name"] { color: #e6edf3 !important; }

  /* Live (live.nicovideo.jp) watch page — the "ニコニ広告" and "ギフト" buttons in
     the comment/interaction bar (and the program-application menu) default to a
     solid #fff square, so two white tiles glared on the dark control bar. Their
     glyph is a mask-image whose own background-color (#666) IS the fill. Repaint
     the tile to a dark elevated surface and lift the glyph to a light fill —
     darkening the glyph bg (the reflex for a "background") would erase it. */
  button[class*="nicoad-button"], button[class*="gift-button"] {
    background-color: #2d333b !important;
  }
  button[class*="nicoad-button"] [class*="symbol-mark"],
  button[class*="gift-button"] [class*="symbol-mark"] {
    background-color: #c4cdd6 !important;
  }
  /* The scheduled-program start-time pill ("5時間後 開始（10分前開場）") in the
     player's watch-rejected overlay is a 90%-white badge with #252525 text — a
     bright blob on the dark stage. Repaint it to a dark pill with a light label. */
  [class*="watch-rejected"] [class*="value-area"] {
    background-color: #2d333b !important; color: #e6edf3 !important;
  }

  /* Live (live.nicovideo.jp) home — the "好みで探す" (konomi-tag) section heading is an
     <h2> whose only child is a banner PNG, sitting on its own #eee fill. The PNG is
     opaque, so the fill is invisible while the image loads correctly — but it is a
     1080x120 light slab the moment the image 404s or has not yet arrived. Dark the well.
     NOTE (verified, do not "fix"): the banner ARTWORK itself is a white-background
     illustration with red accents. It stays as-is — inverting it would flip those reds
     to cyan, and darkening real artwork is worse than a bright banner. */
  section[class*="konomi-tag-list-section"] > header > h2 {
    background-color: #14181d !important;
  }

  /* Live (live.nicovideo.jp) watch page — the "アニメ公式生放送タイムシフト
     ランキング" column (.official-live-ts-ranking) hardcodes a near-white
     #fafafa wrapper fill that no token reaches, so the whole ranking panel
     rendered as a tall white slab: the dark cards floated on it and its own
     light #e6edf3 heading read invisibly light-on-light. Repaint the wrapper
     to the page base; the cards and text inside are already dark-correct. */
  .official-live-ts-ranking { background-color: #14181d !important; }

  /* Live (live.nicovideo.jp) watch page — the program-list carousel's prev/next arrows
     (.page-selector) are #f2f2f2 buttons holding a near-black #1a1a1a chevron. The site
     rests them at opacity .2, so today they render as a grey bar rather than a white
     slab — but the fill underneath is white and the glyph is 1.3:1 against it, so any
     hover/active state that raises the opacity paints a bright column. Repaint the
     button dark and lift the chevron, which is correct at every opacity. */
  [class*="page-selector"] { background-color: #2d333b !important; }
  [class*="page-selector"] svg, [class*="page-selector"] path { fill: #c4cdd6 !important; }

  /* Live (live.nicovideo.jp) watch page — the player's menu-dock buttons (タイムシフト予約 /
     共有 / ポストする) and the comment panel's NG設定 button each raise their tooltip as a
     ::after with `content:`, styled #1a1a1a-on-#f2f2f2. No token reaches them and no
     element-bg scan can see a pseudo, so a white tooltip box popped up over the dark
     player on every hover. Repaint them to the dark tooltip surface used everywhere
     else (matching .tooltip-layer .tooltip above). */
  [class*="program-menu-dock"] button::after,
  [class*="program-menu-dock"] a::after,
  [class*="ng-setting-button"]::after {
    background-color: #2d333b !important;
    color: #e6edf3 !important;
    border-color: #3a424c !important;
  }

  /* Live (live.nicovideo.jp) watch page — each program-description section heading
     ("関連番組", "リンク", "初めてニコニコ生放送をご利用になる方"…) marks itself with a
     10px light-grey (#d1d1d1) left accent bar plus a 1px underline that no token
     reaches, so on the dark theme every heading grew a bright grey bar and rule.
     Soften those dividers to the standard dark component border. Scoped to the
     stable GA-namespace description class (the hashed sibling class is unstable). */
  .ga-ns-description div { border-color: #2d333b !important; }
  /* Broadcasters author the program description as free HTML and commonly wrap
     section headings in a light pastel pill (`<h2 style="background-color:#ffeaff">`
     …「●プレゼントキャンペーン●」/「●出演●」…) that relies on the site's dark default
     text. Our broad `[class*="-description"]` light-text pass reaches those spans, so
     the heading rendered near-white on near-white (~1.4:1). Restore a dark label on any
     description element that carries its OWN inline background — keeping the broadcaster's
     colour and fixing the contrast — while the plain description body (no inline bg) keeps
     the light text it needs on the dark page. Scoped to the live GA-namespace description. */
  .ga-ns-description [style*="background-color"],
  .ga-ns-description [style*="background-color"] * { color: #1a1a1a !important; }

  /* Live (live.nicovideo.jp) watch page — the player's "promotion panel"
     ("プレミアム会員になって番組をより高画質で見よう…") tags its row with an INFO
     type-label pill that keeps a #f2f2f2 white fill no token reaches; our broad
     label text pass then painted its label #c4cdd6, landing light-grey on white at
     ~1.4:1 — an unreadable bright pill on the dark panel. Repaint the pill to a dark
     elevated surface (its label is already light and clears AA there). Scoped to the
     stable GA-namespace panel; the sibling 公式 badge is a dark #1a1a1a pill already. */
  .ga-ns-promotion-panel [class*="type-label"] {
    background-color: #2d333b !important;
  }

  /* Live (live.nicovideo.jp) watch page — the "Xでシェアして応援しよう" promo balloon that
     points at the player's share button is a #e9f2ff light-blue callout (with a matching
     border-triangle pointer drawn as ::after's top border, and a #666 mask-image close
     glyph) that no token reaches, so it floated as a bright box over the dark player.
     Repaint the balloon and its pointer to the dark tooltip surface, lift the label, and
     lighten the close glyph fill (its mask-image background-color IS the X). Scoped to the
     stable GA namespace. */
  .ga-ns-weak-balloon, section[class*="weak-balloon"] {
    background-color: #2d333b !important;
  }
  .ga-ns-weak-balloon::after, section[class*="weak-balloon"]::after {
    border-top-color: #2d333b !important;
  }
  .ga-ns-weak-balloon, .ga-ns-weak-balloon *,
  section[class*="weak-balloon"], section[class*="weak-balloon"] * {
    color: #e6edf3 !important;
  }
  .ga-ns-weak-balloon .close-button::before,
  section[class*="weak-balloon"] .close-button::before {
    background-color: #c4cdd6 !important;
  }

  /* Selected segmented-control pill — the search type tabs (動画 / ショート /
     シリーズ / マイリスト / ユーザー), the comment vs. tag search toggle and
     similar active "inverted" pills paint the active item with the site's
     dark-mode transparentWhite.A95 (#f2f2f2 @95%) fill + transparentGray.A95
     (#1a1a1a @95%) label, which lands as a stark white blob on the near-black
     base. Repaint the active pill with the brand azure surface + a light label,
     matching --colors-tab-base-active above: an elevated GREY here read only
     1.14:1 against the unselected pills' 10%-white track, so "which tab am I
     on" was lost. Scoped to the token's own class so only the SELECTED pill is
     touched (the unselected pills already read correctly on dark). */
  [class*="transparentWhite.A95"] {
    background-color: #1f4a78 !important;
    color: #e6edf3 !important;
    fill: #e6edf3 !important;
  }
  [class*="transparentWhite.A95"] svg,
  [class*="transparentWhite.A95"] path { fill: #e6edf3 !important; }

  /* ============================================================
     Common top header bar (shared chrome) + its two flyouts
     ============================================================ */
  .CommonHeader, [class*="CommonHeader"] { background-color: #0d1117 !important; }
  header [class*="common-header-"] { color: #e6edf3; }

  /* The bar hosts two flyouts, both closed at audit time so no element-bg scan
     ever sees them, and both built from hashed `common-header-*` classes:
       • the "その他" mega-dropdown — a #f4f4f4 panel of #fff service rows;
       • the account panel behind the avatar chevron — a #fafafa panel with a
         #fff login card, a #f4f4f4 section heading and a #f4f4f4 footer strip.
     Both hardcode their surfaces (no design token reaches them) and their row
     labels hardcode #333 / #252525, so once the panel is repainted the labels
     go dark-on-dark.

     Nothing inside either panel is hookable by name: the panel roots, the grid
     and column wrappers, the section heading and the "もっと見る" footer strip are
     pure hashed divs, and the service rows share `pos=header_servicelink` in
     their cmnhd_ref with the eight ALWAYS-VISIBLE nav links of the bar itself.

     The previous rules reached for the Level-4 relational selector twice, and
     both guesses misfired:
       • an anchor matched on "rows have a chevron svg the nav links lack" — the
         bar's own TV-logo anchor has an svg too, so it wore a permanent #1c2128
         rectangle behind the logo on the #252525 bar;
       • a div matched on "contains the コモンズ service link" — the relational
         argument ended in a DESCENDANT, which every ancestor of the flyout also
         satisfies. It matched nine elements up to and including the header bar,
         which flipped #252525 -> #1c2128 for as long as the menu stayed open.

     DEPTH is the discriminator that actually holds. Measured live: the bar's own
     chrome never nests more than six divs deep (the nav links sit at four),
     while everything inside either flyout starts at seven. A plain descendant
     chain selects the flyout interiors exactly — and, being CSS2, it survives
     the .org.css sanitizer that strips relational selectors, so userstyles.org
     finally gets this fix too. */
  #CommonHeader div div div div div div div,
  #CommonHeader div div div div div div div a {
    background-color: #1c2128 !important;
    border-color: #262c33 !important;
    color: #c4cdd6 !important;
  }
  #CommonHeader div div div div div div div a *,
  #CommonHeader div div div div div div div span,
  #CommonHeader div div div div div div div label {
    color: #c4cdd6 !important;
  }
  #CommonHeader div div div div div div div a:hover {
    background-color: #262c33 !important;
  }
  /* One thing in the ALWAYS-VISIBLE bar reaches seven divs too: the wrapper pair
     around the account avatar, which the rule above stamped as a #1c2128 square
     on the #252525 bar. It is the FIRST child of the avatar button, whereas the
     account panel and its click-scrim are that button's later children — so an
     exact child-chain + :first-child isolates the avatar branch and nothing else
     (verified against both flyouts open). */
  #CommonHeader > div > div > div > div > div > div:first-child div {
    background-color: transparent !important;
  }
  /* The account panel's two CTAs are anchors inside that same subtree, so the
     rule above flattened the blue ログイン and orange 新規会員登録 into two identical
     grey rows. They carry the same `pos=userpanel` marker as the plain rows
     around them, so the only thing that separates a CTA from a row is where it
     points: account.nicovideo.jp. Restore the site's own brand fills — same
     chain plus one attribute, so this lands later AND heavier. The ヘッダー追従
     toggle is a <label> + <input>, so its switch colours are never touched. */
  #CommonHeader div div div div div div div a[href*="account.nicovideo.jp/login"] {
    background-color: #498dca !important; color: #ffffff !important;
  }
  #CommonHeader div div div div div div div a[href*="account.nicovideo.jp/register"] {
    background-color: #e5a100 !important; color: #ffffff !important;
  }

  /* Header search autocomplete (nicolib). The suggestion panel hardcodes a #fff
     surface; our legacy text passes then painted every suggestion #c4cdd6, so the
     open dropdown rendered near-white words on white (~1.9:1). The panel only
     exists while a query is typed, so it never appears in a static scan. */
  .nicolib-SuggestSearch {
    background-color: #1c2128 !important; border-color: #2d333b !important;
  }
  .nicolib-SuggestSearch-item.active, .nicolib-SuggestSearch-item:hover,
  .nicolib-SuggestSearch-item > button:hover {
    background-color: #262c33 !important;
  }
  /* The legacy header's search-type pull-down (動画 / 静画 / 生放送) opens onto a
     #f5f5f5 sheet — closed, and therefore invisible, at audit time. */
  .CrossSearch-pullDownList {
